values.content:
=Tu es un conseiller en évolution professionnelle spécialisé dans les reconversions de carrière. Analyse le profil reçu et propose exactement 10 métiers pertinents : 2 proches du métier actuel, 3 évolutions naturelles et 5 reconversions réalistes. Valorise les compétences transférables, les responsabilités et les soft skills. Évite les doublons et utilise des intitulés de métiers connus sur le marché français.

Retourne uniquement un JSON valide, sans bloc Markdown, avec exactement cette structure :
{
  "jobs": [
    {
      "name": "Intitulé du métier",
      "score": 89,
      "description": "Description courte du métier",
      "reason": "Pourquoi ce métier correspond au profil"
    }
  ]
}

Contraintes : jobs contient exactement 10 objets ; score est un entier entre 0 et 100 ; name, description et reason sont des chaînes non vides. N'ajoute aucun autre champ.

Profil reçu : {{ $json.body.toJsonString() }}

parameters.jsCode:
const result = $input.first().json;

const message = Array.isArray(result.output)
  ? result.output.find((entry) => entry.type === "message")
  : undefined;

let text =
  message?.content?.find((entry) => entry.type === "output_text")?.text
  ?? result.output_text
  ?? result.text;

if (typeof text !== "string" || !text.trim()) {
  throw new Error("Le modèle n'a pas renvoyé de JSON.");
}

text = text.trim().replace(/^```(?:json)?\s*|\s*```$/g, "");

let parsed;
try {
  parsed = JSON.parse(text);
} catch {
  throw new Error("La réponse du modèle n'est pas un JSON valide.");
}

const suggestions = Array.isArray(parsed) ? parsed : parsed.jobs;
if (!Array.isArray(suggestions)) {
  throw new Error("La réponse du modèle doit contenir un tableau « jobs ».");
}

const jobs = suggestions.map((job, index) => {
  const name = job.name ?? job.jobTitle ?? job.libelleRome ?? job.intitule;
  const rawScore = Number(job.score ?? job.compatibilityScore ?? job.scorePrediction);
  const score = Math.round(rawScore <= 1 ? rawScore * 100 : rawScore);
  const skills = Array.isArray(job.matchingSkills) ? job.matchingSkills.join(", ") : "";
  const description = job.description ?? skills;
  const reason = job.reason ?? job.contexte;

  if (
    typeof name !== "string" || !name.trim()
    || !Number.isFinite(score) || score < 0 || score > 100
    || typeof description !== "string" || !description.trim()
    || typeof reason !== "string" || !reason.trim()
  ) {
    throw new Error(`Le métier numéro ${index + 1} ne contient pas les champs requis.`);
  }

  return {
    name: name.trim(),
    score,
    description: description.trim(),
    reason: reason.trim()
  };
});

return [{ json: { jobs } }];
